import bisect
import functools
import os

from dataclasses import dataclass
from typing import Dict, List, Optional, Tuple

import numpy as np

from faster_whisper.utils import get_assets_path


# The code below is adapted from https://github.com/snakers4/silero-vad.
@dataclass
class VadOptions:
    """VAD options.

    Attributes:
      threshold: Speech threshold. Silero VAD outputs speech probabilities for each audio chunk,
        probabilities ABOVE this value are considered as SPEECH. It is better to tune this
        parameter for each dataset separately, but "lazy" 0.5 is pretty good for most datasets.
      neg_threshold: Silence threshold for determining the end of speech. If a probability is lower
        than neg_threshold, it is always considered silence. Values higher than neg_threshold
        are only considered speech if the previous sample was classified as speech; otherwise,
        they are treated as silence. This parameter helps refine the detection of speech
         transitions, ensuring smoother segment boundaries.
      min_speech_duration_ms: Final speech chunks shorter min_speech_duration_ms are thrown out.
      max_speech_duration_s: Maximum duration of speech chunks in seconds. Chunks longer
        than max_speech_duration_s will be split at the timestamp of the last silence that
        lasts more than 100ms (if any), to prevent aggressive cutting. Otherwise, they will be
        split aggressively just before max_speech_duration_s.
      min_silence_duration_ms: In the end of each speech chunk wait for min_silence_duration_ms
        before separating it
      speech_pad_ms: Final speech chunks are padded by speech_pad_ms each side
    """

    threshold: float = 0.5
    neg_threshold: float = None
    min_speech_duration_ms: int = 0
    max_speech_duration_s: float = float("inf")
    min_silence_duration_ms: int = 2000
    speech_pad_ms: int = 400


def get_speech_timestamps(
    audio: np.ndarray,
    vad_options: Optional[VadOptions] = None,
    sampling_rate: int = 16000,
    **kwargs,
) -> List[dict]:
    """This method is used for splitting long audios into speech chunks using silero VAD.

    Args:
      audio: One dimensional float array.
      vad_options: Options for VAD processing.
      sampling rate: Sampling rate of the audio.
      kwargs: VAD options passed as keyword arguments for backward compatibility.

    Returns:
      List of dicts containing begin and end samples of each speech chunk.
    """
    if vad_options is None:
        vad_options = VadOptions(**kwargs)

    threshold = vad_options.threshold
    neg_threshold = vad_options.neg_threshold
    min_speech_duration_ms = vad_options.min_speech_duration_ms
    max_speech_duration_s = vad_options.max_speech_duration_s
    min_silence_duration_ms = vad_options.min_silence_duration_ms
    window_size_samples = 512
    speech_pad_ms = vad_options.speech_pad_ms
    min_speech_samples = sampling_rate * min_speech_duration_ms / 1000
    speech_pad_samples = sampling_rate * speech_pad_ms / 1000
    max_speech_samples = (
        sampling_rate * max_speech_duration_s
        - window_size_samples
        - 2 * speech_pad_samples
    )
    min_silence_samples = sampling_rate * min_silence_duration_ms / 1000
    min_silence_samples_at_max_speech = sampling_rate * 98 / 1000

    audio_length_samples = len(audio)

    model = get_vad_model()

    padded_audio = np.pad(
        audio, (0, window_size_samples - audio.shape[0] % window_size_samples)
    )
    speech_probs = model(padded_audio)

    triggered = False
    speeches = []
    current_speech = {}
    if neg_threshold is None:
        neg_threshold = max(threshold - 0.15, 0.01)

    # to save potential segment end (and tolerate some silence)
    temp_end = 0
    # to save potential segment limits in case of maximum segment size reached
    prev_end = next_start = 0

    for i, speech_prob in enumerate(speech_probs):
        if (speech_prob >= threshold) and temp_end:
            temp_end = 0
            if next_start < prev_end:
                next_start = window_size_samples * i

        if (speech_prob >= threshold) and not triggered:
            triggered = True
            current_speech["start"] = window_size_samples * i
            continue

        if (
            triggered
            and (window_size_samples * i) - current_speech["start"] > max_speech_samples
        ):
            if prev_end:
                current_speech["end"] = prev_end
                speeches.append(current_speech)
                current_speech = {}
                # previously reached silence (< neg_thres) and is still not speech (< thres)
                if next_start < prev_end:
                    triggered = False
                else:
                    current_speech["start"] = next_start
                prev_end = next_start = temp_end = 0
            else:
                current_speech["end"] = window_size_samples * i
                speeches.append(current_speech)
                current_speech = {}
                prev_end = next_start = temp_end = 0
                triggered = False
                continue

        if (speech_prob < neg_threshold) and triggered:
            if not temp_end:
                temp_end = window_size_samples * i
            # condition to avoid cutting in very short silence
            if (window_size_samples * i) - temp_end > min_silence_samples_at_max_speech:
                prev_end = temp_end
            if (window_size_samples * i) - temp_end < min_silence_samples:
                continue
            else:
                current_speech["end"] = temp_end
                if (
                    current_speech["end"] - current_speech["start"]
                ) > min_speech_samples:
                    speeches.append(current_speech)
                current_speech = {}
                prev_end = next_start = temp_end = 0
                triggered = False
                continue

    if (
        current_speech
        and (audio_length_samples - current_speech["start"]) > min_speech_samples
    ):
        current_speech["end"] = audio_length_samples
        speeches.append(current_speech)

    for i, speech in enumerate(speeches):
        if i == 0:
            speech["start"] = int(max(0, speech["start"] - speech_pad_samples))
        if i != len(speeches) - 1:
            silence_duration = speeches[i + 1]["start"] - speech["end"]
            if silence_duration < 2 * speech_pad_samples:
                speech["end"] += int(silence_duration // 2)
                speeches[i + 1]["start"] = int(
                    max(0, speeches[i + 1]["start"] - silence_duration // 2)
                )
            else:
                speech["end"] = int(
                    min(audio_length_samples, speech["end"] + speech_pad_samples)
                )
                speeches[i + 1]["start"] = int(
                    max(0, speeches[i + 1]["start"] - speech_pad_samples)
                )
        else:
            speech["end"] = int(
                min(audio_length_samples, speech["end"] + speech_pad_samples)
            )

    return speeches


def collect_chunks(
    audio: np.ndarray,
    chunks: List[dict],
    sampling_rate: int = 16000,
    max_duration: float = float("inf"),
) -> Tuple[List[np.ndarray], List[Dict[str, float]]]:
    """This function merges the chunks of audio into chunks of max_duration (s) length."""
    if not chunks:
        chunk_metadata = {
            "offset": 0,
            "duration": 0,
            "segments": [],
        }
        return [np.array([], dtype=np.float32)], [chunk_metadata]

    audio_chunks = []
    chunks_metadata = []

    current_segments = []
    current_duration = 0
    total_duration = 0
    current_audio = np.array([], dtype=np.float32)

    for chunk in chunks:
        if (
            current_duration + chunk["end"] - chunk["start"]
            > max_duration * sampling_rate
        ):
            audio_chunks.append(current_audio)
            chunk_metadata = {
                "offset": total_duration / sampling_rate,
                "duration": current_duration / sampling_rate,
                "segments": current_segments,
            }
            total_duration += current_duration
            chunks_metadata.append(chunk_metadata)

            current_segments = []

            current_audio = audio[chunk["start"] : chunk["end"]]
            current_duration = chunk["end"] - chunk["start"]
        else:
            current_segments.append(chunk)
            current_audio = np.concatenate(
                (current_audio, audio[chunk["start"] : chunk["end"]])
            )

            current_duration += chunk["end"] - chunk["start"]

    audio_chunks.append(current_audio)

    chunk_metadata = {
        "offset": total_duration / sampling_rate,
        "duration": current_duration / sampling_rate,
        "segments": current_segments,
    }
    chunks_metadata.append(chunk_metadata)
    return audio_chunks, chunks_metadata


class SpeechTimestampsMap:
    """Helper class to restore original speech timestamps."""

    def __init__(self, chunks: List[dict], sampling_rate: int, time_precision: int = 2):
        self.sampling_rate = sampling_rate
        self.time_precision = time_precision
        self.chunk_end_sample = []
        self.total_silence_before = []

        previous_end = 0
        silent_samples = 0

        for chunk in chunks:
            silent_samples += chunk["start"] - previous_end
            previous_end = chunk["end"]

            self.chunk_end_sample.append(chunk["end"] - silent_samples)
            self.total_silence_before.append(silent_samples / sampling_rate)

    def get_original_time(
        self,
        time: float,
        chunk_index: Optional[int] = None,
        is_end: bool = False,
    ) -> float:
        if chunk_index is None:
            chunk_index = self.get_chunk_index(time, is_end)

        total_silence_before = self.total_silence_before[chunk_index]
        return round(total_silence_before + time, self.time_precision)

    def get_chunk_index(self, time: float, is_end: bool = False) -> int:
        sample = int(time * self.sampling_rate)
        if sample in self.chunk_end_sample and is_end:
            return self.chunk_end_sample.index(sample)

        return min(
            bisect.bisect(self.chunk_end_sample, sample),
            len(self.chunk_end_sample) - 1,
        )


@functools.lru_cache
def get_vad_model():
    """Returns the VAD model instance."""
    path = os.path.join(get_assets_path(), "silero_vad_v6.onnx")
    return SileroVADModel(path)


class SileroVADModel:
    def __init__(self, path):
        try:
            import onnxruntime
        except ImportError as e:
            raise RuntimeError(
                "Applying the VAD filter requires the onnxruntime package"
            ) from e

        opts = onnxruntime.SessionOptions()
        opts.inter_op_num_threads = 1
        opts.intra_op_num_threads = 1
        opts.enable_cpu_mem_arena = False
        opts.log_severity_level = 4

        self.session = onnxruntime.InferenceSession(
            path,
            providers=["CPUExecutionProvider"],
            sess_options=opts,
        )

    def __call__(
        self, audio: np.ndarray, num_samples: int = 512, context_size_samples: int = 64
    ):
        assert audio.ndim == 1, "Input should be a 1D array"
        assert (
            audio.shape[0] % num_samples == 0
        ), "Input size should be a multiple of num_samples"

        h = np.zeros((1, 1, 128), dtype="float32")
        c = np.zeros((1, 1, 128), dtype="float32")
        context = np.zeros(
            (1, context_size_samples),
            dtype="float32",
        )

        batched_audio = audio.reshape(-1, num_samples)
        context = batched_audio[..., -context_size_samples:]
        context[-1] = 0
        context = np.roll(context, 1, 0)
        batched_audio = np.concatenate([context, batched_audio], 1)

        batched_audio = batched_audio.reshape(-1, num_samples + context_size_samples)

        encoder_batch_size = 10000
        num_segments = batched_audio.shape[0]
        outputs = []
        for i in range(0, num_segments, encoder_batch_size):
            output, h, c = self.session.run(
                None,
                {"input": batched_audio[i : i + encoder_batch_size], "h": h, "c": c},
            )
            outputs.append(output)

        out = np.concatenate(outputs, axis=0)

        return out

from collections import deque
from typing import Tuple, Optional

class StreamingSileroVAD:
    """流式 Silero VAD 模型：维护 RNN 隐状态，支持逐 chunk (512 samples) 推理"""
    def __init__(self, path):
        try:
            import onnxruntime
        except ImportError as e:
            raise RuntimeError("Streaming VAD requires onnxruntime") from e

        opts = onnxruntime.SessionOptions()
        opts.inter_op_num_threads = 1
        opts.intra_op_num_threads = 1
        opts.enable_cpu_mem_arena = False
        opts.log_severity_level = 4

        self.session = onnxruntime.InferenceSession(
            path, providers=["CPUExecutionProvider"], sess_options=opts,
        )
        self.num_samples = 512
        self.context_size = 64
        self.reset()

    def reset(self):
        # 维护 RNN 的隐状态 (h, c) 和上下文 (context)
        self.h = np.zeros((1, 1, 128), dtype="float32")
        self.c = np.zeros((1, 1, 128), dtype="float32")
        self.context = np.zeros((1, self.context_size), dtype="float32")

    def process_chunk(self, chunk: np.ndarray) -> float:
        """输入 512 samples，返回当前的 speech probability"""
        assert len(chunk) == self.num_samples
        
        # 拼接上一帧的 context 和当前 chunk
        input_chunk = np.concatenate([self.context, chunk.reshape(1, -1)], axis=1)
        output, self.h, self.c = self.session.run(
            None, {"input": input_chunk, "h": self.h, "c": self.c}
        )
        # 更新 context 为当前 chunk 的最后 64 个采样点
        self.context = chunk[-self.context_size:].reshape(1, -1)
        return float(np.squeeze(output))


class StreamingVADIterator:
    """
    流式 VAD 状态机。
    接收音频 chunk，在检测到一句话结束时，返回: (音频片段, 绝对起始秒数, 绝对结束秒数)
    """
    def __init__(self, vad_options: VadOptions, sampling_rate: int = 16000):
        self.sampling_rate = sampling_rate
        self.window_size = 512
        
        # 阈值与样本数转换
        self.threshold = vad_options.threshold
        self.neg_threshold = vad_options.neg_threshold or max(self.threshold - 0.15, 0.01)
        self.min_speech_samples = int(sampling_rate * vad_options.min_speech_duration_ms / 1000)
        self.min_silence_samples = int(sampling_rate * vad_options.min_silence_duration_ms / 1000)
        self.speech_pad_samples = int(sampling_rate * vad_options.speech_pad_ms / 1000)
        
        # 状态机变量 (全部使用绝对样本索引)
        self.triggered = False
        self.speech_start = -1
        self.temp_end = 0
        self.current_idx = 0
        
        # 滑动窗口 Buffer
        self.chunk_buffer = deque()
        self.buffer_samples = 0
        self.buffer_start_idx = 0  # 【新增】chunk_buffer 中第一个 chunk 对应的绝对样本索引
        self.max_buffer_samples = sampling_rate * 30
        
        self.model = StreamingSileroVAD(os.path.join(get_assets_path(), "silero_vad_v6.onnx"))

    def reset(self):
        self.triggered = False
        self.speech_start = -1
        self.temp_end = 0
        self.current_idx = 0
        self.chunk_buffer.clear()
        self.buffer_samples = 0
        self.buffer_start_idx = 0  # 【新增】重置起始索引
        self.model.reset()

    def __call__(self, chunk: np.ndarray) -> Optional[Tuple[np.ndarray, float, float]]:
        assert len(chunk) == self.window_size
        
        prob = self.model.process_chunk(chunk)
        self.chunk_buffer.append(chunk)
        self.buffer_samples += self.window_size
        
        result = None
        
        # 1. 状态机：检测语音开始
        if prob >= self.threshold:
            if self.temp_end > 0: self.temp_end = 0
            if not self.triggered:
                self.triggered = True
                self.speech_start = self.current_idx
                
        # 2. 状态机：检测语音结束
        elif prob < self.neg_threshold and self.triggered:
            if self.temp_end == 0: self.temp_end = self.current_idx
            
            if (self.current_idx - self.temp_end) >= self.min_silence_samples:
                # 计算带 Padding 的绝对边界
                pad_start = max(self.buffer_start_idx, self.speech_start - self.speech_pad_samples)
                pad_end = min(self.buffer_start_idx + self.buffer_samples, self.temp_end + self.speech_pad_samples)
                
                if (self.temp_end - self.speech_start) > self.min_speech_samples:
                    # 【修复核心】将绝对索引转换为相对于 chunk_buffer 的索引
                    start_c = (pad_start - self.buffer_start_idx) // self.window_size
                    end_c = (pad_end - self.buffer_start_idx + self.window_size - 1) // self.window_size
                    
                    # 防御性边界检查
                    start_c = max(0, start_c)
                    end_c = min(len(self.chunk_buffer), end_c)
                    
                    if start_c < end_c:
                        audio = np.concatenate(list(self.chunk_buffer)[start_c:end_c])
                        
                        # 精确裁剪
                        local_start = pad_start - (self.buffer_start_idx + start_c * self.window_size)
                        local_end = pad_end - (self.buffer_start_idx + start_c * self.window_size)
                        final_audio = audio[local_start:local_end].copy()
                        
                        result = (final_audio, pad_start / self.sampling_rate, pad_end / self.sampling_rate)
                    
                # 重置状态，清理已处理的 buffer
                self.triggered = False
                self.speech_start = -1
                self.temp_end = 0
                
                # 计算要保留的 chunk 数量 (pad_end 之后的部分)
                keep_samples = (self.buffer_start_idx + self.buffer_samples) - pad_end
                keep_c = max(0, keep_samples // self.window_size)
                
                if keep_c > 0:
                    self.chunk_buffer = deque(list(self.chunk_buffer)[-keep_c:])
                else:
                    self.chunk_buffer.clear()
                    
                # 【修复核心】更新 buffer_start_idx
                discarded_samples = self.buffer_samples - (keep_c * self.window_size)
                self.buffer_start_idx += discarded_samples
                self.buffer_samples = keep_c * self.window_size

        # 3. 强制截断：如果一句话超过 35 秒，强制切断送入 Whisper
        elif self.triggered and self.buffer_samples >= self.max_buffer_samples:
            pad_start = max(self.buffer_start_idx, self.speech_start - self.speech_pad_samples)
            pad_end = self.buffer_start_idx + self.buffer_samples
            
            start_c = (pad_start - self.buffer_start_idx) // self.window_size
            start_c = max(0, min(start_c, len(self.chunk_buffer)))
            
            if start_c < len(self.chunk_buffer):
                audio = np.concatenate(list(self.chunk_buffer)[start_c:])
                local_start = pad_start - (self.buffer_start_idx + start_c * self.window_size)
                final_audio = audio[local_start:].copy()
                
                result = (final_audio, pad_start / self.sampling_rate, pad_end / self.sampling_rate)
            
            self.reset() # 强制重置

        self.current_idx += self.window_size
        
        # 防止未说话时 buffer 无限增长
        if not self.triggered and self.buffer_samples > self.max_buffer_samples:
            keep_c = self.max_buffer_samples // self.window_size
            
            if keep_c < len(self.chunk_buffer):
                discarded_c = len(self.chunk_buffer) - keep_c
                discarded_samples = discarded_c * self.window_size
                
                self.chunk_buffer = deque(list(self.chunk_buffer)[-keep_c:])
                self.buffer_start_idx += discarded_samples  # 【新增】同步更新起始索引
                self.buffer_samples = keep_c * self.window_size
            
        return result